def check_ap_distinctness(n):
    # Check if there are duplicate sums for an AP, assuming a_i = i (a simplified case)
    # The sum is determined by i+j.
    sums = {}
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            s = i + j
            sums[s] = (i, j)

    # If any sum is generated by more than one pair, the sums are not distinct.
    # Note: We must check if the pairs generating the same sum are different sets.
    # Since i and j are indices, if i+j = k+l, they might correspond to different sets.

    # Let's count how many pairs map to each sum.
    sum_counts = {}
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            s = i + j
            sum_counts[s] = sum_counts.get(s, 0) + 1

    for s, count in sum_counts.items():
        if count > 1:
            print(f"Sum {s} appears {count} times. Not distinct.")
            return True
    return False

# Test for n=3 and n=4
print("--- n=3 test ---")
check_ap_distinctness(3) 
print("\n--- n=4 test ---")
check_ap_distinctness(4)

